import { JSDOM } from 'jsdom';
import * as puppeteer from 'puppeteer';
import { createHash } from 'crypto';
import { EventEmitter } from 'events';

// Feature flag system
interface FeatureFlags {
  enableRichText: boolean;
  enableCustomFonts: boolean;
  enableWatermark: boolean;
  templateCacheEnabled: boolean;
  sanitizationMode: 'strict' | 'relaxed' | 'legacy';
}

const DEFAULT_FLAGS: FeatureFlags = {
  enableRichText: false,
  enableCustomFonts: false,
  enableWatermark: true,
  templateCacheEnabled: true,
  sanitizationMode: 'strict'
};

class FlagResolver {
  private overrides: Map<string, Partial<FeatureFlags>> = new Map();

  resolveForTenant(tenantId: string, base: FeatureFlags): FeatureFlags {
    const override = this.overrides.get(tenantId) || {};
    return { ...base, ...override };
  }

  setOverride(tenantId: string, flags: Partial<FeatureFlags>) {
    this.overrides.set(tenantId, flags);
  }
}

// Template sanitization pipeline
class SanitizationPipeline {
  private readonly ALLOWED_TAGS = ['b', 'i', 'u', 'span', 'div', 'p', 'br', 'table', 'tr', 'td', 'th'];
  private readonly ALLOWED_ATTRS = ['class', 'style', 'data-field'];

  sanitizeStrict(html: string): string {
    const dom = new JSDOM(`<body>${html}</body>`);
    const body = dom.window.document.body;
    this.walkAndClean(body);
    return body.innerHTML;
  }

  sanitizeRelaxed(html: string): string {
    // Relaxed mode allows more tags but still strips scripts
    const dom = new JSDOM(`<body>${html}</body>`);
    const body = dom.window.document.body;
    const scripts = body.querySelectorAll('script');
    scripts.forEach(s => s.remove());
    return body.innerHTML;
  }

  sanitizeLegacy(html: string): string {
    // Legacy mode: regex-based removal for backward compat
    return html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
  }

  private walkAndClean(node: Element) {
    const children = Array.from(node.children);
    for (const child of children) {
      if (!this.ALLOWED_TAGS.includes(child.tagName.toLowerCase())) {
        child.remove();
      } else {
        const attrs = Array.from(child.attributes);
        for (const attr of attrs) {
          if (!this.ALLOWED_ATTRS.includes(attr.name)) {
            child.removeAttribute(attr.name);
          }
        }
        this.walkAndClean(child);
      }
    }
  }
}

// Template interpolation engine
class TemplateEngine {
  private cache: Map<string, string> = new Map();

  interpolate(template: string, variables: Record<string, string>): string {
    const cacheKey = createHash('sha256').update(template).digest('hex');
    let result = template;

    for (const [key, value] of Object.entries(variables)) {
      const placeholder = `{{${key}}}`;
      result = result.split(placeholder).join(value);
    }

    return result;
  }
}

// PDF Generation Service
export class PDFGenerator extends EventEmitter {
  private flagResolver: FlagResolver;
  private sanitizer: SanitizationPipeline;
  private templateEngine: TemplateEngine;

  constructor() {
    super();
    this.flagResolver = new FlagResolver();
    this.sanitizer = new SanitizationPipeline();
    this.templateEngine = new TemplateEngine();
  }

  setTenantFlags(tenantId: string, flags: Partial<FeatureFlags>) {
    this.flagResolver.setOverride(tenantId, flags);
  }

  async generatePDF(
    tenantId: string,
    template: string,
    variables: Record<string, string>,
    userFlags?: Partial<FeatureFlags>
  ): Promise<Buffer> {
    // Resolve feature flags for this tenant
    const baseFlags = { ...DEFAULT_FLAGS, ...(userFlags || {}) };
    const flags = this.flagResolver.resolveForTenant(tenantId, baseFlags);

    // Step 1: Interpolate template with variables
    const interpolated = this.templateEngine.interpolate(template, variables);

    // Step 2: Apply sanitization based on feature flag
    const sanitized = this.applySanitization(interpolated, flags);

    // Step 3: Apply rich text processing if enabled
    const processed = flags.enableRichText
      ? this.processRichText(sanitized, flags)
      : sanitized;

    // Step 4: Render to PDF
    return this.renderHTML(processed, flags);
  }

  private applySanitization(html: string, flags: FeatureFlags): string {
    switch (flags.sanitizationMode) {
      case 'strict':
        return this.sanitizer.sanitizeStrict(html);
      case 'relaxed':
        return this.sanitizer.sanitizeRelaxed(html);
      case 'legacy':
        return this.sanitizer.sanitizeLegacy(html);
      default:
        return this.sanitizer.sanitizeStrict(html);
    }
  }

  private processRichText(html: string, flags: FeatureFlags): string {
    // Rich text processing re-parses to add formatting classes
    const dom = new JSDOM(`<body>${html}</body>`);
    const body = dom.window.document.body;

    // Add PDF-specific styling classes
    const elements = body.querySelectorAll('[data-field]');
    elements.forEach(el => {
      el.classList.add('pdf-field');
    });

    // Feature: custom font injection when enabled
    if (flags.enableCustomFonts) {
      const style = dom.window.document.createElement('style');
      style.textContent = '@import url("https://fonts.internal/custom.css");';
      body.prepend(style);
    }

    return body.innerHTML;
  }

  private async renderHTML(html: string, flags: FeatureFlags): Promise<Buffer> {
    const fullHTML = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>${html}</body></html>`;

    const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox'] });
    const page = await browser.newPage();
    await page.setContent(fullHTML, { waitUntil: 'networkidle0' });

    const pdf = await page.pdf({ format: 'A4' });
    await browser.close();

    return Buffer.from(pdf);
  }
}

// API handler
export async function handlePDFRequest(req: {
  tenantId: string;
  template: string;
  variables: Record<string, string>;
  flags?: Partial<FeatureFlags>;
}): Promise<Buffer> {
  const generator = new PDFGenerator();

  // Tenant-specific flag: enterprise tenants get legacy mode for compat
  if (req.tenantId.startsWith('enterprise-')) {
    generator.setTenantFlags(req.tenantId, { sanitizationMode: 'legacy' });
  }

  return generator.generatePDF(req.tenantId, req.template, req.variables, req.flags);
}
